// The Worker's entry point: OpenNext's generated worker (the whole Next.js
// app) plus a cron handler. wrangler.jsonc points `main` here.
//
// The cron (triggers.crons in wrangler.jsonc) doesn't do the work itself — it
// calls the app's own /api/cron route, so the work runs inside Next.js with
// the same database access and code as everything else. The request never
// leaves the Worker; the token keeps anyone else from calling the route.

// Generated by `opennextjs-cloudflare build` — absent until the first build.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "./.open-next/worker.js";
import { cronToken } from "./src/lib/clauwi/cron-token";

export default {
  fetch: handler.fetch,

  async scheduled(_controller, env, ctx) {
    const request = new Request(`${env.SITE_URL}/api/cron`, {
      method: "POST",
      headers: { authorization: `Bearer ${await cronToken(env.AUTH_SECRET)}` },
    });
    ctx.waitUntil(
      (handler.fetch(request, env, ctx) as Promise<Response>).then(async (res) => {
        if (!res.ok) console.error("cron run failed", res.status, await res.text().catch(() => ""));
      }),
    );
  },
} satisfies ExportedHandler<CloudflareEnv>;
